import json
from pathlib import Path
import generate_summary


def _make_report_file(tmp_path, content, filename="analyse-abc123def456.md"):
    filepath = tmp_path / filename
    filepath.write_text(content)
    return filepath


def _build_content(commit="abc123def456", subject="测试补丁", what="测试意图", dims=None):
    if dims is None:
        dims = {}
    json_obj = {
        "commit": commit,
        "补丁标题": subject,
        "补丁意图描述": what,
        "变更维度": dims,
    }
    json_str = json.dumps(json_obj, ensure_ascii=False, indent=2)
    return f"# 分析报告\n\n一些内容。\n\n{json_str}\n"


def test_dimension_marked_no_change_is_excluded(tmp_path):
    """变更类型为'无变更'的维度不应出现在解析结果中。"""
    dims = {
        "对外接口变更": {
            "变更类型": "无变更",
            "变更影响描述": "有一些影响描述",
            "用户适配建议": "有一些适配建议",
        }
    }
    filepath = _make_report_file(tmp_path, _build_content(dims=dims))
    parser = generate_summary.ReportParser(filepath)
    result = parser.parse()
    assert len(result["dimensions"]) == 0

