import json
from pathlib import Path
import generate_summary


def _make_report_file(tmp_path, content, filename="analyse-abc123def456.md"):
    filepath = tmp_path / filename
    filepath.write_text(content)
    return filepath


def _build_content(commit="abc123def456", subject="测试补丁", what="测试意图", dims=None):
    if dims is None:
        dims = {}
    json_obj = {
        "commit": commit,
        "补丁标题": subject,
        "补丁意图描述": what,
        "变更维度": dims,
    }
    json_str = json.dumps(json_obj, ensure_ascii=False, indent=2)
    return f"# 分析报告\n\n一些内容。\n\n{json_str}\n"


def test_dimension_with_real_change_type_is_included(tmp_path):
    """有实际变更类型的维度应出现在解析结果中。"""
    dims = {
        "对外接口变更": {
            "变更类型": "新增",
            "变更影响描述": "新增了API",
            "用户适配建议": "更新调用方",
        }
    }
    filepath = _make_report_file(tmp_path, _build_content(dims=dims))
    parser = generate_summary.ReportParser(filepath)
    result = parser.parse()
    assert len(result["dimensions"]) == 1
    assert result["dimensions"][0]["dim_name"] == "对外接口变更"
    assert result["dimensions"][0]["change_type"] == "新增"


def test_dimension_with_empty_change_type_but_intent_is_excluded(tmp_path):
    """变更类型为空但变更影响描述非空时，维度不应出现在结果中。"""
    dims = {
        "命令行行为变更": {
            "变更类型": "",
            "变更影响描述": "有影响描述",
            "用户适配建议": "",
        }
    }
    filepath = _make_report_file(tmp_path, _build_content(dims=dims))
    parser = generate_summary.ReportParser(filepath)
    result = parser.parse()
    assert len(result["dimensions"]) == 0


def test_dimension_with_empty_change_type_but_adaptation_is_excluded(tmp_path):
    """变更类型为空但用户适配建议非空时，维度不应出现在结果中。"""
    dims = {
        "配置文件变更": {
            "变更类型": "",
            "变更影响描述": "",
            "用户适配建议": "有适配建议",
        }
    }
    filepath = _make_report_file(tmp_path, _build_content(dims=dims))
    parser = generate_summary.ReportParser(filepath)
    result = parser.parse()
    assert len(result["dimensions"]) == 0


def test_mixed_dimensions_only_real_changes_included(tmp_path):
    """混合多种维度时，只有有实际变更类型的维度应出现在结果中。"""
    dims = {
        "对外接口变更": {
            "变更类型": "无变更",
            "变更影响描述": "无影响",
            "用户适配建议": "无需适配",
        },
        "命令行行为变更": {
            "变更类型": "修改",
            "变更影响描述": "修改了行为",
            "用户适配建议": "更新脚本",
        },
        "配置文件变更": {
            "变更类型": "",
            "变更影响描述": "有影响描述",
            "用户适配建议": "有适配建议",
        },
    }
    filepath = _make_report_file(tmp_path, _build_content(dims=dims))
    parser = generate_summary.ReportParser(filepath)
    result = parser.parse()
    assert len(result["dimensions"]) == 1
    assert result["dimensions"][0]["dim_name"] == "命令行行为变更"
    assert result["dimensions"][0]["change_type"] == "修改"


def test_basic_field_parsing(tmp_path):
    """基本字段（commit、标题、意图描述）应被正确解析。"""
    dims = {
        "对外接口变更": {
            "变更类型": "新增",
            "变更影响描述": "新增API",
            "用户适配建议": "更新调用方",
        }
    }
    filepath = _make_report_file(
        tmp_path,
        _build_content(
            commit="abc123def456",
            subject="测试补丁标题",
            what="测试补丁意图描述",
            dims=dims,
        ),
    )
    parser = generate_summary.ReportParser(filepath)
    result = parser.parse()
    assert result["hash"] == "abc123def456"
    assert result["subject"] == "测试补丁标题"
    assert result["what"] == "测试补丁意图描述"
    assert result["parse_errors"] == []
